﻿/**
 * test-cli.mjs - the CLI builds ANY project
 *
 * The gate that makes rosefd a framework instead of a demo: `rosefd
 * build [dir]` compiles a project that is not this repository, defaults to
 * the current directory, reads that project's rosefd.config.js, and fails
 * loudly instead of silently emitting an empty dist/.
 *
 * Run: node tests/test-cli.mjs   (needs the repo's node_modules; run from the repo root)
 */

import { spawn } from 'node:child_process';
import * as fs from 'node:fs';
import * as path from 'node:path';
import * as zlib from 'node:zlib';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';

const REPO = process.cwd();
const TSX = [path.join(REPO, 'node_modules/tsx/dist/cli.mjs'), path.join(REPO, 'src/cli/index.ts')];

let checks = 0;
function assert(cond, msg) {
  checks++;
  if (!cond) {
    console.error('FAIL: ' + msg);
    process.exit(1);
  }
  console.log('ok - ' + msg);
}

/** Run the CLI with args, in cwd; resolve with { code, out, err }. */
function run(args, cwd) {
  return new Promise((resolve) => {
    const p = spawn(process.execPath, [...TSX, ...args], { cwd });
    let out = '';
    let err = '';
    p.stdout.on('data', (c) => { out += c; });
    p.stderr.on('data', (c) => { err += c; });
    p.on('close', (code) => resolve({ code, out, err }));
  });
}

async function stopChild(p) {
  if (!p || p.exitCode !== null) return;
  p.kill();
  await Promise.race([
    new Promise((resolve) => p.once('close', resolve)),
    new Promise((resolve) => setTimeout(resolve, 1500)),
  ]);
  if (p.exitCode !== null) return;
  p.kill('SIGKILL');
  await new Promise((resolve) => p.once('close', resolve));
}

async function rmTreeStable(dir) {
  for (let i = 0; i < 30; i++) {
    try {
      fs.rmSync(dir, { recursive: true, force: true });
      return;
    } catch (e) {
      if (e?.code !== 'ENOTEMPTY' || i === 29) throw e;
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }
}

